import sys
root = sys.argv[1]


def patch(path, pairs):
    s = open(root + '/' + path).read()
    for old, new in pairs:
        assert s.count(old) == 1, (path, old[:80])
        s = s.replace(old, new)
    open(root + '/' + path, 'w').write(s)


